#include <algorithm>
#include <array>
#include <cstdint>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <random>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using R=vector<unsigned>;using Z=unsigned long long;
void need(bool x,const char*s){if(!x)throw runtime_error(s);}
int pc(unsigned x){return __builtin_popcount(x);}int bit(unsigned x){return __builtin_ctz(x);}
R extend(R r,unsigned m){int n=r.size();for(int i=0;i<n;i++)if(!(m>>i&1))r[i]|=1<<n;r.push_back(m);return r;}
R canon(R const&r){int n=r.size();map<int,vector<int>>g;for(int i=0;i<n;i++)g[pc(r[i])].push_back(i);vector<vector<int>>gs;for(auto const&[d,v]:g)gs.push_back(v);vector<int>p;R best;function<void(int)>go=[&](int k){if(k==(int)gs.size()){R a(n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(r[p[i]]>>p[j]&1)a[i]|=1<<j;if(best.empty()||a<best)best=a;return;}auto q=gs[k];do{p.insert(p.end(),q.begin(),q.end());go(k+1);p.resize(p.size()-q.size());}while(next_permutation(q.begin(),q.end()));};go(0);return best;}
int matching(R const&r,int root){int n=r.size();vector<int>mate(n,-1);function<bool(int,unsigned&)>aug=[&](int u,unsigned&seen){for(int v=0;v<n;v++)if(v!=root&&(r[v]>>root&1)&&(r[u]>>v&1)&&!(seen>>v&1)){seen|=1<<v;if(mate[v]<0||aug(mate[v],seen)){mate[v]=u;return true;}}return false;};int k=0;for(int u=0;u<n;u++)if(r[root]>>u&1){unsigned seen=0;k+=aug(u,seen);}return k;}
vector<Z> gaps(R const&r,int root){int n=r.size();vector<int>old;for(int v=0;v<n;v++)if(v!=root)old.push_back(v);int q=old.size();if(!q)return {1,1};int N=1<<q,J=n+1;vector<Z>d(size_t(N)*q*J);auto at=[&](int m,int v,int j)->Z&{return d[(size_t(m)*q+v)*J+j];};for(int v=0;v<q;v++){at(1<<v,v,0)=1;at(1<<v,v,1)=r[root]>>old[v]&1;}for(int m=1;m<N;m++)for(int u=0;u<q;u++)if(m>>u&1)for(int v=0;v<q;v++)if(!(m>>v&1)){bool edge=r[old[u]]>>old[v]&1,gap=(r[old[u]]>>root&1)&&(r[root]>>old[v]&1);for(int j=0;j<J;j++){if(edge)at(m|1<<v,v,j)+=at(m,u,j);if(gap&&j+1<J)at(m|1<<v,v,j+1)+=at(m,u,j);}}vector<Z>a(J);for(int u=0;u<q;u++)for(int j=0;j<J;j++){a[j]+=at(N-1,u,j);if((r[old[u]]>>root&1)&&j+1<J)a[j+1]+=at(N-1,u,j);}return a;}
Z side(R const&r,int root,unsigned C,bool left){int n=r.size();vector<int>V,cover;for(int v=0;v<n;v++)if(v!=root){if(C>>v&1)cover.push_back(v);else if(bool(r[root]>>v&1)==left)V.push_back(v);}int q=V.size(),N=1<<q;R a(q);for(int i=0;i<q;i++)for(int j=0;j<q;j++)if(left?(r[V[i]]>>V[j]&1):(r[V[j]]>>V[i]&1))a[i]|=1<<j;vector<vector<Z>>d(N,vector<Z>(q));for(int i=0;i<q;i++)d[1<<i][i]=1;for(int m=1;m<N;m++)for(int v=0;v<q;v++)if(d[m][v]){unsigned z=a[v]&~m;while(z){unsigned b=z&-z;z-=b;d[m|b][bit(b)]+=d[m][v];}}vector<Z>f(N);f[0]=1;for(int m=1;m<N;m++)f[m]=accumulate(d[m].begin(),d[m].end(),Z(0));for(int c:cover){vector<Z>b(N),next(N);bool cO=r[root]>>c&1;b[0]=left?cO:!cO;for(int m=1;m<N;m++)for(int v=0;v<q;v++)if(left?(r[V[v]]>>c&1):(r[c]>>V[v]&1))b[m]+=d[m][v];for(int m=0;m<N;m++){int s=m;for(;;){next[m]+=b[s]*f[m^s];if(!s)break;s=(s-1)&m;}}f=move(next);}return f[N-1];}

vector<Z> ends(R const&r,vector<int>V,bool reverse){int q=V.size(),N=1<<q;vector<vector<Z>>dp(N,vector<Z>(q));for(int v=0;v<q;v++)dp[1<<v][v]=1;for(int m=1;m<N;m++)for(int u=0;u<q;u++)if(dp[m][u])for(int v=0;v<q;v++)if(!(m>>v&1)&&(reverse?(r[V[v]]>>V[u]&1):(r[V[u]]>>V[v]&1)))dp[m|1<<v][v]+=dp[m][u];vector<Z>out(r.size());for(int v=0;v<q;v++)out[V[v]]=dp[N-1][v];return out;}
long long signed_count(R const&r,int root){vector<int>V;for(int v=0;v<(int)r.size();v++)if(v!=root)V.push_back(v);int q=V.size();if(!q)return 0;int N=1<<q;vector<vector<long long>>dp(N,vector<long long>(q));for(int v=0;v<q;v++)if(r[V[v]]>>root&1)dp[1<<v][v]=1;for(int m=1;m<N;m++)for(int u=0;u<q;u++)if(dp[m][u])for(int v=0;v<q;v++)if(!(m>>v&1)){int w=int(r[V[u]]>>V[v]&1)-int((r[V[u]]>>root&1)&&(r[root]>>V[v]&1));dp[m|1<<v][v]+=w*dp[m][u];}long long out=0;for(int v=0;v<q;v++)if(r[root]>>V[v]&1)out+=dp[N-1][v];return out;}
struct Stats{long long graphs=0,roots=0,rankzero=0,rankone=0,centers=0,negative=0,zero=0,positive_ranktwo=0,negative_ranktwo=0;};
void test(R const&r,Stats&z){z.graphs++;int n=r.size();for(int root=0;root<n;root++){z.roots++;auto a=gaps(r,root);long long boundary=0;for(int j=0;j<(int)a.size();j++)boundary+=(j&1)?-(long long)a[j]:a[j];need(boundary==signed_count(r,root),"signed separator identity");int nu=matching(r,root);if(nu==0){z.rankzero++;need(boundary==0,"zero-rank boundary");}if(nu==2){z.positive_ranktwo+=boundary>0;z.negative_ranktwo+=boundary<0;}if(nu!=1)continue;z.rankone++;z.negative+=boundary<0;z.zero+=boundary==0;need(boundary<=0,"rank-one sign");vector<int>O,I;for(int v=0;v<n;v++)if(v!=root)(r[root]>>v&1?O:I).push_back(v);auto so=ends(r,O,true),eo=ends(r,O,false),si=ends(r,I,true),ei=ends(r,I,false);int centers=0;for(int c=0;c<n;c++)if(c!=root){bool cover=true;for(int u:O)for(int v:I)if((r[u]>>v&1)&&c!=u&&c!=v)cover=false;if(!cover)continue;centers++;z.centers++;Z product=0;if(r[root]>>c&1){Z e=0;for(int v:I)if(r[c]>>v&1)e+=ei[v];product=so[c]*e;}else{Z s=0;for(int u:O)if(r[u]>>c&1)s+=so[u];product=ei[c]*s;}need(boundary==-(long long)product,"endpoint boundary factor");}need(centers>0,"rank-one cover center");}}
void emit(const char*label,Stats const&s){cout<<'"'<<label<<"\":{\"graphs\":"<<s.graphs<<",\"roots\":"<<s.roots<<",\"rank_zero\":"<<s.rankzero<<",\"rank_one\":"<<s.rankone<<",\"cover_centers\":"<<s.centers<<",\"negative_rank_one\":"<<s.negative<<",\"zero_rank_one\":"<<s.zero<<",\"negative_rank_two\":"<<s.negative_ranktwo<<",\"positive_rank_two\":"<<s.positive_ranktwo<<'}';}
int main(){for(auto row:vector<R>{{16,5,9,3,14},{2,20,9,3,13}}){need(matching(row,1)==2,"literal rank-two hostile");auto a=gaps(row,1);vector<Z>expected=(row[0]==16)?vector<Z>{5,15,11,2,0,0}:vector<Z>{1,11,17,4,0,0};need(a==expected,"literal hostile run profile");}Stats U,L,Rnd;set<R>bank{{0}};vector<int>sizes;for(int n=1;n<=7;n++){if(n>1){set<R>next;for(auto const&r:bank)for(unsigned m=0;m<(1u<<(n-1));m++)next.insert(canon(extend(r,m)));bank=move(next);}sizes.push_back(bank.size());for(auto const&r:bank)test(r,U);}need(sizes==vector<int>({1,1,2,4,12,56,456}),"complete small bank");for(int n=1;n<=5;n++){vector<pair<int,int>>E;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)E.push_back({i,j});for(unsigned m=0;m<(1u<<E.size());m++){R r(n);for(int j=0;j<(int)E.size();j++){auto[a,b]=E[j];if(m>>j&1)r[a]|=1<<b;else r[b]|=1<<a;}test(r,L);}}mt19937 rng(1971111);for(int n=8;n<=13;n++)for(int rep=0;rep<12;rep++){R r(n);for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)if(rng()&1)r[a]|=1<<b;else r[b]|=1<<a;test(r,Rnd);}cout<<'{';emit("complete_unlabelled_through7",U);cout<<',';emit("complete_labelled_through5",L);cout<<',';emit("seeded_larger",Rnd);cout<<",\"status\":\"PASS\"}\n";}
